import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D21_4UK8.js";const g=JSON.parse('{"title":"🎙️ Master Audio Engineering Guide: 1x12 Hardwood Cab Lab & Studio Mic Mixer","description":"","frontmatter":{},"headers":[],"relativePath":"audio-mics-guide.md","filePath":"audio-mics-guide.md"}'),s={name:"audio-mics-guide.md"};function i(r,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="🎙️-master-audio-engineering-guide-1x12-hardwood-cab-lab-studio-mic-mixer" tabindex="-1">🎙️ Master Audio Engineering Guide: 1x12 Hardwood Cab Lab &amp; Studio Mic Mixer <a class="header-anchor" href="#🎙️-master-audio-engineering-guide-1x12-hardwood-cab-lab-studio-mic-mixer" aria-label="Permalink to &quot;🎙️ Master Audio Engineering Guide: 1x12 Hardwood Cab Lab &amp; Studio Mic Mixer&quot;">​</a></h1><h3 id="evm-12l-cone-acoustics-phase-physics-dual-miking-the-single-track-stereo-secret" tabindex="-1">EVM-12L Cone Acoustics, Phase Physics, Dual Miking &amp; The Single-Track Stereo Secret <a class="header-anchor" href="#evm-12l-cone-acoustics-phase-physics-dual-miking-the-single-track-stereo-secret" aria-label="Permalink to &quot;EVM-12L Cone Acoustics, Phase Physics, Dual Miking &amp; The Single-Track Stereo Secret&quot;">​</a></h3><p><strong>TattooYou Vintage Amplifier &amp; Studio Suite | Main St Audio Labs</strong></p><hr><h1 id="part-i-acoustic-physical-foundations" tabindex="-1">PART I: ACOUSTIC &amp; PHYSICAL FOUNDATIONS <a class="header-anchor" href="#part-i-acoustic-physical-foundations" aria-label="Permalink to &quot;PART I: ACOUSTIC &amp; PHYSICAL FOUNDATIONS&quot;">​</a></h1><hr><h2 id="🔊-1-the-evm-12l-driver-solid-hardwood-cabinet" tabindex="-1">🔊 1. The EVM-12L Driver &amp; Solid Hardwood Cabinet <a class="header-anchor" href="#🔊-1-the-evm-12l-driver-solid-hardwood-cabinet" aria-label="Permalink to &quot;🔊 1. The EVM-12L Driver &amp; Solid Hardwood Cabinet&quot;">​</a></h2><h3 id="a-zero-speaker-breakup-infinite-headroom" tabindex="-1">A. Zero Speaker Breakup &amp; Infinite Headroom <a class="header-anchor" href="#a-zero-speaker-breakup-infinite-headroom" aria-label="Permalink to &quot;A. Zero Speaker Breakup &amp; Infinite Headroom&quot;">​</a></h3><p>Traditional guitar speakers (such as classic 25W or 30W British paper cones) exhibit non-linear distortion: when pushed by tube power, the paper membrane flexes and distorts, adding harsh upper-mid grit and compressing low-end punch.</p><p>The <strong>Electro-Voice EVM-12L</strong> (200W–300W continuous rating, massive 16 lb / 7.5 kg ceramic magnet, cast aluminum frame) was engineered for the exact opposite acoustic philosophy:</p><ul><li><strong>Pristine Fidelity &amp; Pure Tube Dynamics:</strong> The cone does not smear or distort the incoming signal. Every nuance of harmonic texture and saturation comes <strong>directly from the 6L6 power tubes and the &#39;78 Mark I preamp circuit</strong>.</li><li><strong>Surgical String Separation:</strong> Complex chord voicings and open tunings (such as Keith Richards’ open-G riffing) retain distinct string clarity without turning into muddy sonic sludge.</li></ul><h3 id="b-solid-hardwood-cabinet-with-bass-reflex-porting" tabindex="-1">B. Solid Hardwood Cabinet with Bass-Reflex Porting <a class="header-anchor" href="#b-solid-hardwood-cabinet-with-bass-reflex-porting" aria-label="Permalink to &quot;B. Solid Hardwood Cabinet with Bass-Reflex Porting&quot;">​</a></h3><p>Unlike standard open-back pine combo boxes, this cabinet is crafted from <strong>solid hardwood</strong> with a tuned front bass port:</p><ul><li><strong>Tight, Fast Low-End:</strong> The tuned port resonance reinforces frequencies between <strong>80 Hz and 160 Hz</strong> with critical damping, eliminating muddy boominess and delivering instantaneous transient punch on heavy palm mutes.</li></ul><hr><h2 id="🎯-2-speaker-cone-acoustics-mic-placement-matrix" tabindex="-1">🎯 2. Speaker Cone Acoustics: Mic Placement Matrix <a class="header-anchor" href="#🎯-2-speaker-cone-acoustics-mic-placement-matrix" aria-label="Permalink to &quot;🎯 2. Speaker Cone Acoustics: Mic Placement Matrix&quot;">​</a></h2><p>A 12-inch guitar cone does not radiate sound uniformly. Moving the capsule from the center dust cap toward the outer surround naturally rolls off high-end presence while enhancing low-mid body:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>                  │                 SPEAKER CONE                 │</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │      ( -3 )      ( -2 )      ( -1 )   ( 0 )  │</span></span>
<span class="line"><span>                  │      Outer        Cone      Cap Edge   Center │</span></span>
<span class="line"><span>                  │     (Dark)       (Warm)     (Sweet)   (Bright)│</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │  [ PORT ]  &lt;─── (Tuned Bass-Reflex Port)     │</span></span>
<span class="line"><span>                  └──────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">Take</th><th style="text-align:left;">Physical Position</th><th style="text-align:left;">Frequency Response</th><th style="text-align:left;">Sonic Character &amp; Ideal Application</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>0: Direct</code></strong></td><td style="text-align:left;"><strong>Center / Dust Cap</strong></td><td style="text-align:left;">Strong boost at <strong>4 kHz – 8 kHz</strong>.</td><td style="text-align:left;">Razor-sharp pick attack, ultra-bright and articulate. Cuts through dense mixes and percussive funk lines.</td></tr><tr><td style="text-align:center;"><strong><code>+1: Edge</code></strong></td><td style="text-align:left;"><strong>Cap Outer Edge</strong></td><td style="text-align:left;">Clear presence with smooth high-end roll-off.</td><td style="text-align:left;">Classic rock rhythm bite with punchy definition.</td></tr><tr><td style="text-align:center;"><strong><code>-1: Sweet</code></strong></td><td style="text-align:left;"><strong>Cap-to-Cone Transition</strong></td><td style="text-align:left;">Balanced, musical curve (<strong>Studio Sweet Spot</strong>).</td><td style="text-align:left;"><strong>The Studio Benchmark:</strong> Perfect balance of tight lows, rich mids, and silky highs. The recommended starting point for any style.</td></tr><tr><td style="text-align:center;"><strong><code>-2: Warm</code></strong></td><td style="text-align:left;"><strong>Mid Cone Surface</strong></td><td style="text-align:left;">Warm midrange, smooth rolloff above 5 kHz.</td><td style="text-align:left;">Off-axis smoothness. Perfect for taming bright bridge single-coils (Telecaster, Stratocaster).</td></tr><tr><td style="text-align:center;"><strong><code>-3: Dark</code></strong></td><td style="text-align:left;"><strong>Outer Cone Edge</strong></td><td style="text-align:left;">Deep lows, muted top-end.</td><td style="text-align:left;">Thick, vintage jazz warmth, smoky blues, or heavy downtuned chugging.</td></tr><tr><td style="text-align:center;"><strong><code>Port: Bass</code></strong></td><td style="text-align:left;"><strong>Bass-Reflex Vent</strong></td><td style="text-align:left;">Focused energy boost at <strong>80 Hz – 160 Hz</strong>.</td><td style="text-align:left;">Captures frontal air resonance. Adds visceral 4x12-style chest thump.</td></tr><tr><td style="text-align:center;"><strong><code>Room 3D</code></strong></td><td style="text-align:left;"><strong>Live Room Ambient Pair</strong></td><td style="text-align:left;">3D acoustic dimension and natural early reflections.</td><td style="text-align:left;">Spaced studio stereo condenser pair. Removes artificial &quot;dry box&quot; feeling and places the amp in a real physical room.</td></tr></tbody></table><hr><h2 id="🎧-3-the-physical-asymmetry-left-l-vs-right-r-takes" tabindex="-1">🎧 3. The Physical Asymmetry: Left (L) vs. Right (R) Takes <a class="header-anchor" href="#🎧-3-the-physical-asymmetry-left-l-vs-right-r-takes" aria-label="Permalink to &quot;🎧 3. The Physical Asymmetry: Left (L) vs. Right (R) Takes&quot;">​</a></h2><p>Every position includes dedicated <strong><code>L</code> (Left)</strong> and <strong><code>R</code> (Right)</strong> takes (e.g., <code>57 L -1</code> and <code>57 R -1</code>):</p><h3 id="why-do-they-sound-subtly-distinct-on-a-circular-cone" tabindex="-1">Why do they sound subtly distinct on a circular cone? <a class="header-anchor" href="#why-do-they-sound-subtly-distinct-on-a-circular-cone" aria-label="Permalink to &quot;Why do they sound subtly distinct on a circular cone?&quot;">​</a></h3><ol><li><strong>Voice-Coil Tinsel Lead Mass:</strong> The flexible braided wires connecting the terminals to the moving coil (<em>tinsel leads</em>) are physically soldered to one side of the cone. This microscopic mass difference alters the harmonic vibration between left and right hemispheres.</li><li><strong>Hardwood Grain Resonance:</strong> Natural wood grain density and internal air circulation create nuanced acoustic asymmetries that high-end studio microphones capture in detail.</li></ol><hr><h2 id="🔬-4-phase-physics-zero-destructive-cancellation" tabindex="-1">🔬 4. Phase Physics: Zero Destructive Cancellation <a class="header-anchor" href="#🔬-4-phase-physics-zero-destructive-cancellation" aria-label="Permalink to &quot;🔬 4. Phase Physics: Zero Destructive Cancellation&quot;">​</a></h2><h3 id="a-the-comb-filtering-trap" tabindex="-1">A. The Comb Filtering Trap <a class="header-anchor" href="#a-the-comb-filtering-trap" aria-label="Permalink to &quot;A. The Comb Filtering Trap&quot;">​</a></h3><p>In a physical tracking room, placing two mics in front of a speaker with a minor distance discrepancy of just 1 to 2 millimeters causes arrival time delays:</p><ul><li>Frequencies whose wavelength matches that micro-delay collide at $180^\\circ$ out of phase and <strong>destructively cancel</strong>.</li><li><strong>The sonic result:</strong> The guitar loses low-end weight and collapses into a thin, hollow, nasal tone.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                WAVE MIC A:    ──/\\──\\/──/\\──\\/──</span></span>
<span class="line"><span>                WAVE MIC B:    ──\\/──/\\──\\/──/\\──  (180° Out of Phase)</span></span>
<span class="line"><span>                               ──────────────────</span></span>
<span class="line"><span>                SUMMED OUTPUT: ────────────────  (Cancellation / Hollow Box Tone!)</span></span></code></pre></div><h3 id="b-sample-accurate-phase-alignment-in-tattooyou" tabindex="-1">B. Sample-Accurate Phase Alignment in TattooYou <a class="header-anchor" href="#b-sample-accurate-phase-alignment-in-tattooyou" aria-label="Permalink to &quot;B. Sample-Accurate Phase Alignment in TattooYou&quot;">​</a></h3><p>In <strong>TattooYou</strong>, all cabinet impulse responses underwent <strong>Minimum Phase Transform</strong>:</p><ol><li>Every mic capture starts precisely at <strong>sample zero ($t = 0$)</strong>.</li><li><strong>Positive Phase Correlation ($&gt; +0.92$):</strong> Low and midrange fundamentals (80 Hz to 3 kHz) correlate at nearly $+1.0$. <strong>Low frequencies sum constructively with maximum punch</strong>.</li><li><strong>High-Frequency Phase Texture (&gt; 4 kHz):</strong> Subtle high-frequency micro-variations provide natural analog smoothing without comb filtering.</li></ol><hr><h2 id="🎛️-5-microphone-profiles" tabindex="-1">🎛️ 5. Microphone Profiles <a class="header-anchor" href="#🎛️-5-microphone-profiles" aria-label="Permalink to &quot;🎛️ 5. Microphone Profiles&quot;">​</a></h2><h3 id="_1-shure-57-cardioid-dynamic" tabindex="-1">1. Shure 57 (Cardioid Dynamic) <a class="header-anchor" href="#_1-shure-57-cardioid-dynamic" aria-label="Permalink to &quot;1. Shure 57 (Cardioid Dynamic)&quot;">​</a></h3><ul><li><strong>Character:</strong> The undisputed industry standard of rock history.</li><li><strong>Response:</strong> Signature presence peak at <strong>3 kHz – 6 kHz</strong> that pushes the guitar to the front of the mix with aggressive pick bite.</li></ul><h3 id="_2-neumann-87-large-diaphragm-condenser" tabindex="-1">2. Neumann 87 (Large Diaphragm Condenser) <a class="header-anchor" href="#_2-neumann-87-large-diaphragm-condenser" aria-label="Permalink to &quot;2. Neumann 87 (Large Diaphragm Condenser)&quot;">​</a></h3><ul><li><strong>Character:</strong> Audiophile-grade studio fidelity (<em>Hi-Fi</em>).</li><li><strong>Response:</strong> Ultra-linear wide bandwidth, deep lows, velvety midrange body, and silky &quot;air&quot; above 10 kHz.</li></ul><h3 id="_3-u87-room-l-room-r-stereo-ambient-pair" tabindex="-1">3. U87 Room L / Room R (Stereo Ambient Pair) <a class="header-anchor" href="#_3-u87-room-l-room-r-stereo-ambient-pair" aria-label="Permalink to &quot;3. U87 Room L / Room R (Stereo Ambient Pair)&quot;">​</a></h3><ul><li><strong>Character:</strong> Captures the three-dimensional acoustic signature of the live tracking room.</li><li><strong>Use Case:</strong> Perfect for headphone monitoring or adding authentic spatial depth without relying on artificial reverb plugins.</li></ul><hr><h1 id="part-ii-how-it-applies-to-tattoo-you" tabindex="-1">PART II: HOW IT APPLIES TO TATTOO YOU <a class="header-anchor" href="#part-ii-how-it-applies-to-tattoo-you" aria-label="Permalink to &quot;PART II: HOW IT APPLIES TO TATTOO YOU&quot;">​</a></h1><hr><h2 id="🎛️-6-dsp-architecture-dual-convolution-engine-in-parallel" tabindex="-1">🎛️ 6. DSP Architecture: Dual-Convolution Engine in Parallel <a class="header-anchor" href="#🎛️-6-dsp-architecture-dual-convolution-engine-in-parallel" aria-label="Permalink to &quot;🎛️ 6. DSP Architecture: Dual-Convolution Engine in Parallel&quot;">​</a></h2><p>Instead of restricting you to a single static IR file, <strong>TattooYou</strong> runs two parallel zero-latency convolution engines (<code>cab1Convolution</code> and <code>cab2Convolution</code>) with an equal-power crossfade curve:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                                  PREAMP &amp; 6L6 POWER AMP SIGNAL</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                       ┌────────────────────────┴────────────────────────┐</span></span>
<span class="line"><span>                       ▼                                                 ▼</span></span>
<span class="line"><span>             [ CONVOLUTION MIC 1 ]                             [ CONVOLUTION MIC 2 ]</span></span>
<span class="line"><span>             Take: 57 L (-1) Sweet                             Take: 87 L (0) Direct (or 57 R)</span></span>
<span class="line"><span>             Fader: -24 dB to +6 dB                            Fader: -24 dB to +6 dB</span></span>
<span class="line"><span>             Weight: w1                                        Phase: Normal / Invert (Ø)</span></span>
<span class="line"><span>                       │                                       Weight: w2</span></span>
<span class="line"><span>                       │                                                 │</span></span>
<span class="line"><span>                       └────────────────────────┬────────────────────────┘</span></span>
<span class="line"><span>                                                ▼</span></span>
<span class="line"><span>                                   CAB LAB MASTER SECTION</span></span>
<span class="line"><span>                                (Equal-Power BLEND Control)</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                        ┌───────────────────────┴───────────────────────┐</span></span>
<span class="line"><span>                        ▼                                               ▼</span></span>
<span class="line"><span>               MONO SUM MODE                                  STEREO SPREAD 3D MODE</span></span>
<span class="line"><span>          Center-summed composite:                       Left Channel  = Mic 1 * (w1 * √2)</span></span>
<span class="line"><span>          Out = (Mic1 * w1) + (Mic2 * w2)                Right Channel = Mic 2 * (w2 * √2)</span></span></code></pre></div><hr><h2 id="⚖️-7-mono-sum-vs-stereo-spread-tailoring-your-mix" tabindex="-1">⚖️ 7. MONO SUM vs. STEREO SPREAD: Tailoring Your Mix <a class="header-anchor" href="#⚖️-7-mono-sum-vs-stereo-spread-tailoring-your-mix" aria-label="Permalink to &quot;⚖️ 7. MONO SUM vs. STEREO SPREAD: Tailoring Your Mix&quot;">​</a></h2><p>The true versatility of TattooYou lies in choosing between the two output modes based on the arrangement:</p><hr><h3 id="a-mono-sum-stereo-spread-disabled" tabindex="-1">A. MONO SUM (Stereo Spread Disabled) <a class="header-anchor" href="#a-mono-sum-stereo-spread-disabled" aria-label="Permalink to &quot;A. MONO SUM (Stereo Spread Disabled)&quot;">​</a></h3><p>Both microphones process the signal and sum directly into the center of the track.</p><h4 id="when-to-use-mono-sum" tabindex="-1">When to Use Mono Sum? <a class="header-anchor" href="#when-to-use-mono-sum" aria-label="Permalink to &quot;When to Use Mono Sum?&quot;">​</a></h4><ul><li>Primary rhythm guitars in dense full-band mixes (heavy drums, bass, keys, and vocals).</li><li>Traditional mono guitar tracks requiring a <strong>tight, punchy, focused center-stage image</strong>.</li></ul><h4 id="how-to-apply-blend-in-mono" tabindex="-1">How to Apply Blend in Mono? <a class="header-anchor" href="#how-to-apply-blend-in-mono" aria-label="Permalink to &quot;How to Apply Blend in Mono?&quot;">​</a></h4><ol><li><p><strong>The Cone Averaging Trick (Summing L + R Takes of the SAME Mic):</strong></p><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code></li><li><strong>Mic 2:</strong> <code>57 R (-1) Sweet</code></li><li><strong>Blend at 50% in Mono:</strong><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Take 57 &quot;L&quot; ──┐</span></span>
<span class="line"><span>              ├───&gt; MONO SUM ───&gt; NATURAL ANALOG PHASE SMOOTHING</span></span>
<span class="line"><span>Take 57 &quot;R&quot; ──┘</span></span></code></pre></div></li><li><strong>The Acoustic Result:</strong> Because high-frequency resonant peaks occur at slightly different frequencies on the left and right hemispheres of the cone, summing them in mono averages out harsh spikes. You get a dense, thick, organic midrange with rounded top-end without reaching for an EQ.</li></ul></li><li><p><strong>Dynamic + Condenser Synergy (Bite + Hi-Fi Body):</strong></p><ul><li><strong>70% Mic 1 (57 Sweet) + 30% Mic 2 (87 Direct):</strong> 57 delivers pick bite and aggression; 87 infuses deep lows and hi-fi air.</li></ul></li><li><p><strong>Sub-Low Injection (Bite + BassPort):</strong></p><ul><li><strong>75% Mic 1 (57 Sweet) + 25% Mic 2 (57 BassPort):</strong> Preserves pick articulation while adding heavy 4x12-style low-end weight.</li></ul></li></ol><hr><h3 id="b-stereo-spread-3d-stereo-spread-enabled" tabindex="-1">B. STEREO SPREAD 3D (Stereo Spread Enabled) <a class="header-anchor" href="#b-stereo-spread-3d-stereo-spread-enabled" aria-label="Permalink to &quot;B. STEREO SPREAD 3D (Stereo Spread Enabled)&quot;">​</a></h3><p>Mic 1 routes to the Left channel and Mic 2 routes to the Right channel with automatic <strong>+3 dB ($\\sqrt{2}$)</strong> loudness compensation.</p><h4 id="🚀-the-single-track-stereo-double-trick-zero-track-duplication" tabindex="-1">🚀 The Single-Track Stereo Double Trick (<em>Zero Track Duplication</em>) <a class="header-anchor" href="#🚀-the-single-track-stereo-double-trick-zero-track-duplication" aria-label="Permalink to &quot;🚀 The Single-Track Stereo Double Trick (*Zero Track Duplication*)&quot;">​</a></h4><ul><li><strong>No need to clone DAW tracks:</strong> You don&#39;t need to record two separate tracks, nudge timing, or insert widening plugins that cause phase issues.</li><li><strong>Organic 3D Space:</strong> By feeding each ear a nuanced micro-perspective from the same cabinet, your brain perceives the <strong>true physical dimensions of an amplifier in a live room</strong>.</li></ul><h4 id="how-to-apply-blend-in-stereo-mode" tabindex="-1">How to Apply Blend in Stereo Mode? <a class="header-anchor" href="#how-to-apply-blend-in-stereo-mode" aria-label="Permalink to &quot;How to Apply Blend in Stereo Mode?&quot;">​</a></h4><ol><li><strong>Wide Double Tracking:</strong><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code> (Left ear).</li><li><strong>Mic 2:</strong> <code>57 R (-1) Sweet</code> (Right ear).</li><li><strong>Blend at 50%:</strong> Expansive, crystal-clear analog stereo width for rhythm guitars on a single track.</li></ul></li><li><strong>Studio Live Room 3D:</strong><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code> (Direct front tone on the left).</li><li><strong>Mic 2:</strong> <code>87 Room L 3D</code> (Ambient live room reflections on the right).</li><li><strong>Blend at 25%–30%:</strong> Natural depth that places the guitar organically in the stereo soundstage.</li></ul></li><li><strong>Fatigue-Free Headphone Tracking:</strong><ul><li>Playing with headphones in Stereo Spread mode removes the auditory fatigue associated with centered &quot;in-your-head&quot; mono signals.</li></ul></li></ol><hr><h3 id="📊-production-quick-guide-mono-vs-stereo" tabindex="-1">📊 Production Quick-Guide: Mono vs. Stereo <a class="header-anchor" href="#📊-production-quick-guide-mono-vs-stereo" aria-label="Permalink to &quot;📊 Production Quick-Guide: Mono vs. Stereo&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Production Scenario</th><th style="text-align:center;">Recommended Mode</th><th style="text-align:left;">Mic 1 / Mic 2 Configuration</th><th style="text-align:center;">Suggested Blend</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Heavy Full-Band Rhythm Guitar</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>87 L Direct</code></td><td style="text-align:center;"><strong>30% to 40%</strong></td></tr><tr><td style="text-align:left;"><strong>Taming Harsh Top-End / Thick Midrange</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 R Sweet</code></td><td style="text-align:center;"><strong>50% (L + R Sum)</strong></td></tr><tr><td style="text-align:left;"><strong>Drop-Tuned Chugs / Heavy Riffs</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 L BassPort</code></td><td style="text-align:center;"><strong>20% to 30%</strong></td></tr><tr><td style="text-align:left;"><strong>Stereo Rhythm on a Single DAW Track</strong></td><td style="text-align:center;"><strong>STEREO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 R Sweet</code></td><td style="text-align:center;"><strong>50% (Centered)</strong></td></tr><tr><td style="text-align:left;"><strong>Intros, Clean Arpeggios &amp; Ambient Solos</strong></td><td style="text-align:center;"><strong>STEREO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>87 Room L 3D</code></td><td style="text-align:center;"><strong>25% to 35%</strong></td></tr><tr><td style="text-align:left;"><strong>Direct Classic Solo Lead</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <em>Off</em></td><td style="text-align:center;"><strong>0% (100% Mic 1)</strong></td></tr><tr><td style="text-align:left;"><strong>Acoustic / Hi-Fi Transparent Chords</strong></td><td style="text-align:center;"><strong>MONO / STEREO</strong></td><td style="text-align:left;">Mic 1: <code>87 L Direct</code> + Mic 2: <code>87 R Open</code></td><td style="text-align:center;"><strong>50%</strong></td></tr></tbody></table><hr><h2 id="🏆-8-studio-reference-presets" tabindex="-1">🏆 8. Studio Reference Presets <a class="header-anchor" href="#🏆-8-studio-reference-presets" aria-label="Permalink to &quot;🏆 8. Studio Reference Presets&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 1. 🎸 Studio Standard  ──&gt; 57 L Sweet + 87 L Direct  (Blend 30%, Mono)</span></span>
<span class="line"><span> 2. 🥊 Heavy Punch      ──&gt; 57 L Sweet + 57 L BassPort (Blend 25%, Mono)</span></span>
<span class="line"><span> 3. 🌌 Live Room 3D     ──&gt; 57 L Sweet + 87 Room L 3D  (Blend 25%, Stereo)</span></span>
<span class="line"><span> 4. 🎧 Wide Double Track──&gt; 57 L Sweet + 57 R Sweet   (Blend 50%, Stereo)</span></span>
<span class="line"><span> 5. ⚡ Solo 57 Classic  ──&gt; 57 L Sweet (Mic 2 Off, Mono)</span></span>
<span class="line"><span> 6. ✨ Solo 87 Hi-Fi    ──&gt; 87 L Direct (Mic 2 Off, Mono)</span></span></code></pre></div><hr><h2 id="💡-9-daw-workflow-tips" tabindex="-1">💡 9. DAW Workflow Tips <a class="header-anchor" href="#💡-9-daw-workflow-tips" aria-label="Permalink to &quot;💡 9. DAW Workflow Tips&quot;">​</a></h2><ol><li><strong>Front-Panel Rapid Tweak:</strong> Use the <strong><code>BLEND</code></strong> mini-knob on the upper-right faceplate to adjust the balance during playback without opening the overlay window.</li><li><strong>Full Console Access:</strong> Click the <strong><code>CAB LAB</code></strong> button or the microphone display to access faders, polarity reverse ($\\varnothing$), and stereo toggles.</li><li><strong>Guaranteed Mono Compatibility:</strong> Thanks to sample-accurate alignment ($t=0$), playback on mono devices (smartphones, mono smart speakers) retains <strong>full volume and low-end impact with zero phase cancellation</strong>.</li></ol>`,73)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
